body{font-family:Arial,sans-serif;max-width:600px;margin:40px auto;color:#1A2E23;font-size:13px}
h1{color:#0F4C2A;font-size:24px;margin-bottom:2px}.sub{color:#5A8A6A;font-size:11px;margin-bottom:20px}
