<tbody>${rows}<tr class="total-row"><td colspan="3">Total</td><td style="text-align:right">${fmtUSD(invoice.total)}</td></tr></tbody></table>
<div class="footer">Merci pour votre confiance · Speranza Della Pharma</div>
</body></html>`);
